select * from customer;
--Q1. what is total revenue generated by male vs female customer
select gender, sum(purchase_amount) as Total_Revenue
from customer 
group by gender;

--Q2. Which customers used discount still spent more than average amount
select customer_id,purchase_amount 
from customer 
where discount_applied='Yes' and purchase_amount > (select avg (purchase_amount) from customer);

--Q3. Which Top 5 product  highest avg rating
select top 5 item_purchased , round(avg(review_rating),2) as avg_rating 
from customer 
group by item_purchased
order by avg_rating desc;

--Q4. Compare avg price between express and standard shipping 
select shipping_type,round(avg(purchase_amount),2) as avg_amount 
from customer 
where shipping_type in('Express' , 'Standard')
group by shipping_type
;

--Q5 Compare spending pattern of subscriber and non-subscriber using total and average spent 
select count(customer_id) as total_customers, subscription_status, round(avg(purchase_amount*1.0),2) as avg_amount , round(sum(purchase_amount*1.0),2) as total_spent
from customer
group by subscription_status;

--Q6 Top 5 perecentage purchase when discount applied
select top 5 item_purchased  , 
ROUND(100 * SUM(CASE when discount_applied='Yes' then 1 else 0  end )/ count(*)  ,2) as discount_percentage
from customer
group by item_purchased
order by discount_percentage desc;

--Q7 Customer segment into new returning loyal and count them
with cust_type as 
(
select customer_id , previous_purchases ,
CASE 
  When previous_purchases between 1 and 5 then 'New'
  When previous_purchases between 5 and 20 then 'Returning'
  else 'Loyal'
  end as cust_category
  from customer
)

select cust_category , count(*) as total_cust_count
from cust_type
group by cust_category


-- Q8 top 3 most purchased product within eeach category 
with itm_count as(
select category , item_purchased ,
count(customer_id) as total_cust ,
Row_number() over (partition by category order by count(customer_id) desc) as itm_rnk
from customer
group by category , item_purchased
)

select itm_rnk , category , item_purchased , total_cust 
from itm_count 
where itm_rnk <=3 ;